// Flatten comment threads; keep recent top-level comments with no reply yet that weren't written by the channel
const s = $('Set channel and settings').first().json;
const since = DateTime.now().minus({ hours: s.lookback_hours });
const out = [];
$input.all().forEach((item, i) => {
  const video = $('Keep recent videos').itemMatching(i).json;
  for (const t of item.json.items || []) {
    const c = t.snippet.topLevelComment.snippet;
    if (t.snippet.totalReplyCount > 0) continue;
    if (c.authorChannelId?.value === s.channel_id) continue;
    if (DateTime.fromISO(c.publishedAt) < since) continue;
    out.push({ json: { comment_id: t.snippet.topLevelComment.id, video_id: video.video_id, video_title: video.title,
      author: c.authorDisplayName, text: (c.textOriginal || '').slice(0, 1500), likes: c.likeCount, published_at: c.publishedAt,
      link: `https://www.youtube.com/watch?v=${video.video_id}&lc=${t.snippet.topLevelComment.id}` } });
  }
});
return out.slice(0, s.max_comments_per_run);

// Join each AI result to its comment, drop ones that need no reply, sort by priority
const rank = { high: 0, normal: 1, low: 2 };
return $input.all().map((item, i) => ({ c: $('Skip comments already drafted').itemMatching(i).json, o: item.json.output }))
  .filter(x => x.o.needs_reply)
  .sort((a, b) => (rank[a.o.priority] ?? 3) - (rank[b.o.priority] ?? 3))
  .map(({ c, o }) => ({ json: { drafted_at: $now.toFormat('yyyy-MM-dd HH:mm'), priority: o.priority, category: o.category,
    video_title: c.video_title, author: c.author, comment: c.text, reply_draft: o.reply, summary: o.summary, link: c.link,
    comment_id: c.comment_id, status: 'to review' } }));
